int x;
int y;
int trigger_time_ms;
int path_index;
int entry_count = 0;
for (path_index = 0; path_index < 6; ++path_index) {
    builder.spawns[entry_count].pos = quest_vec2_t((float)(path_index * 72 + 256), 256.0f);
    builder.spawns[entry_count].template_id = SPAWN_ID_DEN_SPIDER_WEAK_10;
    builder.spawns[entry_count].trigger_time_ms = path_index * 900 + 500;
    builder.spawns[entry_count].count = 1;
    ++entry_count;
}
for (; path_index < 12; ++path_index) {
    builder.spawns[entry_count].pos = quest_vec2_t(688.0f, (float)((path_index - 6) * 72 + 256));
    builder.spawns[entry_count].template_id = SPAWN_ID_DEN_SPIDER_WEAK_10;
    builder.spawns[entry_count].trigger_time_ms = path_index * 900 + 500;
    builder.spawns[entry_count].count = 1;
    ++entry_count;
}
